UNION ALL SELECT UNISTR('\0644\0627 \064A\0642\0631\0631 \0623\062D\062F \0637\0644\0628\0627\062A \0627\0644\0645\0648\0638\0641 \0627\0644\0645\0631\062A\0628\0637 \0628\062D\0633\0627\0628\0647.') AR, 'No one decides the requests of the employee linked to their own account.' EN FROM DUAL
UNION ALL SELECT UNISTR('\0644\0644\0625\062C\0627\0632\0629 \0628\0627\0644\0633\0627\0639\0627\062A: \0648\0642\062A \0627\0644\0628\062F\0627\064A\0629 \0641\064A \0623\0648\0644 \064A\0648\0645 \0648\0648\0642\062A \0627\0644\0646\0647\0627\064A\0629 \0641\064A \0622\062E\0631 \064A\0648\0645 (\0645\062B\0644 08:00 \0648 11:00). \0641\0627\0631\063A\0627\0646: \0623\064A\0627\0645 \0643\0627\0645\0644\0629.') AR, 'For leave by the hour: the start time on the first day and the end time on the last day (e.g. 08:00 and 11:00). Both empty: whole days.' EN FROM DUAL
