UNION ALL SELECT UNISTR('\0645\0648\0638\0641\0648\0646 \0622\062E\0631\0648\0646 \0628\0627\0644\0637\0644\0628 \0646\0641\0633\0647 (\0623\0631\0642\0627\0645\0647\0645)') AR, 'Other employees with the same request (their numbers)' EN FROM DUAL
