-- ---------------------------------------------------------------- hdr_core.pks
CREATE OR REPLACE PACKAGE HDR_CORE AS
  -- Hader for Oracle APEX (native): settings, text helpers, the terminal command queue and the
  -- distribution of employees, templates and photos to the terminals of their areas.

  TYPE t_kv IS TABLE OF NVARCHAR2(4000) INDEX BY VARCHAR2(60);

  -- the Hader release these objects belong to: the APEX app warns when it is newer than them
  c_version CONSTANT VARCHAR2(20) := '2.3.6';

  -- TRUE while a terminal's upload is stored: the change triggers stay quiet (the upload distributes
  -- what it changes itself and marks its own days)
  g_quiet BOOLEAN := FALSE;

  -- settings ------------------------------------------------------------
  FUNCTION setting (p_key IN VARCHAR2, p_default IN VARCHAR2 DEFAULT NULL) RETURN VARCHAR2;
  PROCEDURE set_setting (p_key IN VARCHAR2, p_value IN VARCHAR2);
  FUNCTION on_ (p_key IN VARCHAR2) RETURN BOOLEAN;           -- a Y/N setting
  FUNCTION writing RETURN BOOLEAN;                           -- changes may be sent to the terminals
  FUNCTION server_tz (p_sn IN VARCHAR2 DEFAULT NULL) RETURN NUMBER;   -- hours, for the terminals
  -- the clock the terminals keep: the database's time in the zone set for the terminal (adms.timezone); the
  -- database's own clock when none is set
  FUNCTION local_now (p_sn IN VARCHAR2 DEFAULT NULL) RETURN DATE;

  -- text ------------------------------------------------------------------
  FUNCTION to_text (p_body IN BLOB) RETURN NCLOB;           -- UTF-8, older Arabic code page per line
  FUNCTION to_utf8 (p_text IN NCLOB) RETURN BLOB;
  FUNCTION kv (p_text IN NVARCHAR2, p_sep IN VARCHAR2 DEFAULT CHR(9)) RETURN t_kv;   -- keys lower-case
  FUNCTION kv_big (p_line IN NCLOB, p_key IN VARCHAR2, p_sep IN VARCHAR2 DEFAULT CHR(9)) RETURN CLOB;
  FUNCTION get (p_kv IN t_kv, p_key IN VARCHAR2, p_default IN NVARCHAR2 DEFAULT NULL) RETURN NVARCHAR2;
  FUNCTION num (p_value IN NVARCHAR2, p_default IN NUMBER DEFAULT 0) RETURN NUMBER;
  FUNCTION parse_time (p_text IN NVARCHAR2) RETURN DATE;
  FUNCTION valid_pin (p_pin IN VARCHAR2) RETURN BOOLEAN;
  FUNCTION field (p_text IN VARCHAR2, p_n IN PLS_INTEGER, p_sep IN VARCHAR2 DEFAULT CHR(9)) RETURN VARCHAR2;  -- n-th, empty ones count
  FUNCTION tsv_safe (p_value IN NVARCHAR2) RETURN NVARCHAR2;  -- no tab / newline inside a value
  FUNCTION dev_time (p_when IN DATE) RETURN NUMBER;           -- the terminals' compact clock value
  FUNCTION b64_blob (p_text IN CLOB) RETURN BLOB;             -- base64 text (line breaks and all) to its bytes

  -- the hours of an employee's working day on a date (hader/day_hours.py): of the rules hr.day_hours_rules that hold
  -- (hours|from|to|attendance type ids|department codes|name, ";" between), the one starting last; else the hours the
  -- employee's attendance type that day has most often; else hr.day_hours (7)
  FUNCTION day_hours (p_emp IN VARCHAR2, p_day IN DATE) RETURN NUMBER;

  -- terminal options (Key=Value lines kept in HDR_DEVICES.OPTIONS) ----------
  FUNCTION opt (p_sn IN VARCHAR2, p_key IN VARCHAR2) RETURN VARCHAR2;
  PROCEDURE apply_info (p_sn IN VARCHAR2, p_info IN t_kv);    -- merge INFO / options keys

  -- command queue -----------------------------------------------------------
  FUNCTION is_change (p_content IN NVARCHAR2) RETURN BOOLEAN;   -- anything but INFO / DATA QUERY
  FUNCTION queue (p_sn IN VARCHAR2, p_content IN NCLOB, p_title IN NVARCHAR2 DEFAULT NULL) RETURN NUMBER;
  PROCEDURE queue (p_sn IN VARCHAR2, p_content IN NCLOB, p_title IN NVARCHAR2 DEFAULT NULL);
  PROCEDURE requeue_stale (p_minutes IN NUMBER DEFAULT 15, p_max_attempts IN NUMBER DEFAULT 3);

  -- command texts -------------------------------------------------------------
  -- as much of a name as a terminal's name field holds (24 bytes: about 12 Arabic letters), never half a letter
  FUNCTION terminal_name (p_name IN NVARCHAR2, p_bytes IN NUMBER DEFAULT 24) RETURN NVARCHAR2;
  FUNCTION whole_words (p_held IN NVARCHAR2, p_full IN NVARCHAR2) RETURN BOOLEAN;
  FUNCTION name_bytes (p_sn IN VARCHAR2) RETURN NUMBER;
  FUNCTION cmd_user (p_emp_code IN VARCHAR2, p_sn IN VARCHAR2 DEFAULT NULL) RETURN NCLOB;
  FUNCTION cmd_user_delete (p_emp_code IN VARCHAR2) RETURN NCLOB;
  FUNCTION cmd_query (p_table IN VARCHAR2, p_pin IN VARCHAR2 DEFAULT NULL) RETURN NCLOB;
  FUNCTION cmd_query_attlog (p_from IN DATE, p_to IN DATE) RETURN NCLOB;

  -- employees on terminals ------------------------------------------------------
  FUNCTION uses_biodata (p_sn IN VARCHAR2) RETURN BOOLEAN;
  FUNCTION push_employee (p_sn IN VARCHAR2, p_emp_code IN VARCHAR2, p_with_bio IN BOOLEAN DEFAULT TRUE) RETURN NUMBER;
  FUNCTION sync_device (p_sn IN VARCHAR2) RETURN NUMBER;     -- every employee of its area (checks capacity)
  FUNCTION employee_changed (p_emp_code IN VARCHAR2, p_old_areas IN VARCHAR2 DEFAULT NULL,
                             p_with_bio IN BOOLEAN DEFAULT FALSE) RETURN NUMBER;   -- p_old_areas: 'id,id'
  FUNCTION employee_removed (p_emp_code IN VARCHAR2, p_areas IN VARCHAR2) RETURN NUMBER;
  -- people, every kind of template and the photos a terminal holds; p_again 'Y' (asked by a person): table
  -- queries tried once more even if the terminal refused them before
  FUNCTION pull_bio (p_sn IN VARCHAR2, p_pin IN VARCHAR2 DEFAULT NULL, p_again IN VARCHAR2 DEFAULT 'N') RETURN NUMBER;
  -- the terminal sends everything it holds again by itself: its marks cleared, its options read again
  FUNCTION resend_everything (p_sn IN VARCHAR2) RETURN NUMBER;
  -- it refused a table query (-1004): remembered, the other queries waiting closed, everything asked the other way
  PROCEDURE no_table_queries (p_sn IN VARCHAR2);
  FUNCTION bio_delete (p_emp_code IN VARCHAR2, p_kinds IN VARCHAR2, p_fingers IN VARCHAR2 DEFAULT NULL,
                       p_terminals IN BOOLEAN DEFAULT TRUE) RETURN NUMBER;
  PROCEDURE distribute_user (p_emp_code IN VARCHAR2, p_source_sn IN VARCHAR2);
  PROCEDURE distribute_template (p_bio_id IN NUMBER, p_source_sn IN VARCHAR2);
  -- The card picture (HADER_EMP_PHOTOS with SOURCE HAND, DEVICE or NULL) is what a terminal shows when the
  -- employee punches. The recognition photo (HDR_BIO_PHOTOS; SOURCE CAPTURE where it stands in on the pages)
  -- is what it learns the face from, and is never sent as the card picture.
  PROCEDURE distribute_userpic (p_emp_code IN VARCHAR2, p_source_sn IN VARCHAR2);
  PROCEDURE withdraw_userpic (p_emp_code IN VARCHAR2, p_source_sn IN VARCHAR2);   -- the terminals drop theirs
  PROCEDURE userpic_back (p_emp_code IN VARCHAR2, p_sn IN VARCHAR2);   -- the chosen one again (not in a loop)
  -- a terminal holding the person without the name kept here (enrolled there by number only) or with another
  -- one is sent it (not in a loop); p_held: the name it holds
  PROCEDURE name_back (p_emp_code IN VARCHAR2, p_sn IN VARCHAR2, p_held IN NVARCHAR2);
  FUNCTION is_recognition_photo (p_emp_code IN VARCHAR2, p_pic IN BLOB) RETURN BOOLEAN;
  PROCEDURE distribute_photo (p_emp_code IN VARCHAR2, p_bio_type IN NUMBER, p_source_sn IN VARCHAR2);
  -- the recognition photo to every terminal of the employee's areas (they learn the face from it); how many
  FUNCTION send_photo (p_emp_code IN VARCHAR2, p_bio_type IN NUMBER DEFAULT 9) RETURN NUMBER;
  PROCEDURE mark_dirty (p_emp_code IN VARCHAR2, p_day IN DATE);
  PROCEDURE mark_days (p_emp_code IN VARCHAR2, p_from IN DATE, p_to IN DATE);   -- past and today only
  PROCEDURE mark_pending (p_kind IN VARCHAR2, p_key IN VARCHAR2, p_added IN VARCHAR2 DEFAULT NULL,
                          p_removed IN VARCHAR2 DEFAULT NULL, p_deleted IN BOOLEAN DEFAULT FALSE,
                          p_from IN DATE DEFAULT NULL);

  -- terminal settings sent as commands ---------------------------------------------
  PROCEDURE set_server (p_sn IN VARCHAR2, p_host IN VARCHAR2, p_port IN NUMBER, p_reboot IN BOOLEAN DEFAULT TRUE);
  PROCEDURE set_clock (p_sn IN VARCHAR2, p_when IN DATE DEFAULT NULL);
  PROCEDURE simple (p_sn IN VARCHAR2, p_action IN VARCHAR2);  -- info, check, reboot, clear_log, clear_photo, clear_data
  PROCEDURE set_option (p_sn IN VARCHAR2, p_key IN VARCHAR2, p_value IN NVARCHAR2);
  PROCEDURE enroll (p_sn IN VARCHAR2, p_emp_code IN VARCHAR2, p_bio_type IN NUMBER, p_finger IN NUMBER DEFAULT 0);

  -- errors raised to APEX pages
  e_read_only EXCEPTION;
  PRAGMA EXCEPTION_INIT (e_read_only, -20601);
  e_capacity EXCEPTION;
  PRAGMA EXCEPTION_INIT (e_capacity, -20602);
END HDR_CORE;
/

