-- ---------------------------------------------------------------- hdr_license.pks
CREATE OR REPLACE PACKAGE HDR_LICENSE AS
  -- The activation key of Hader for Oracle APEX, checked in the database itself (no Hader server, Oracle 11g and
  -- later, no DBMS_CRYPTO needed): the key the vendor signs (hader/license.py, RSA PKCS#1 v1.5 with SHA-256), bound
  -- to this database (db_code). The free edition takes FREE_TERMINALS terminals; a key takes the number it says.

  FREE_TERMINALS CONSTANT PLS_INTEGER := 2;

  -- this database, as a key is made for it: shown on the settings page, sent to the vendor
  FUNCTION db_code RETURN VARCHAR2;
  -- FULL (the institution's own install: no limit) or FREE (the public edition)
  FUNCTION edition RETURN VARCHAR2;
  -- how many terminals this edition takes: NULL = no limit (the full edition, or a key without a limit)
  FUNCTION terminals_allowed RETURN NUMBER;
  -- the key's fields when it is valid for this database, else raises -20990 with the reason
  PROCEDURE check_key (p_key IN VARCHAR2, p_plan OUT VARCHAR2, p_terminals OUT NUMBER, p_expires OUT VARCHAR2);
  -- a key given on the settings page: checked, then kept (license.key)
  PROCEDURE set_key (p_key IN VARCHAR2);

  -- the building blocks, open for the tests
  FUNCTION sha256 (p_data IN RAW) RETURN RAW;
  FUNCTION rsa_public (p_sig IN RAW, p_n IN VARCHAR2, p_r2 IN VARCHAR2, p_np IN NUMBER) RETURN RAW;
  FUNCTION verify (p_payload IN RAW, p_sig IN RAW, p_n IN VARCHAR2 DEFAULT NULL, p_r2 IN VARCHAR2 DEFAULT NULL,
                   p_np IN NUMBER DEFAULT NULL) RETURN BOOLEAN;
  FUNCTION b64url (p_text IN VARCHAR2) RETURN RAW;
END HDR_LICENSE;
/

