-- ---------------------------------------------------------------- hdr_adms.pks
CREATE OR REPLACE PACKAGE HDR_ADMS AS
  -- What the terminals talk to: ORDS hands every /iclock/* request to handle() (see hdr_ords.sql).
  --
  --   GET  /iclock/cdata?SN=..&options=all        -> settings block (handshake)
  --   POST /iclock/cdata?SN=..&table=ATTLOG       -> punches
  --   POST /iclock/cdata?SN=..&table=OPERLOG      -> users, templates, photos, operation log
  --   GET  /iclock/getrequest?SN=..               -> heartbeat; answered with C:<id>:<command> lines
  --   POST /iclock/devicecmd?SN=..                -> results of those commands
  --   POST /iclock/querydata?SN=..&tablename=..   -> answers to DATA QUERY tablename=..
  --   GET  /iclock/rtdata?SN=..&type=time         -> the server clock

  PROCEDURE handle (p_path IN VARCHAR2, p_method IN VARCHAR2, p_body IN BLOB DEFAULT NULL);

  -- the same without HTTP (tests, and replaying a stored request)
  FUNCTION process (p_path IN VARCHAR2, p_method IN VARCHAR2, p_query IN VARCHAR2, p_ip IN VARCHAR2,
                    p_body IN BLOB, p_status OUT NUMBER) RETURN NCLOB;

  FUNCTION verify_name (p_verify IN NUMBER) RETURN VARCHAR2;
  FUNCTION state_name (p_state IN NUMBER) RETURN VARCHAR2;
  -- punch lines kept aside with a database error ('error <code>', before an upgrade or a lock let them through)
  -- saved again; the number of punches added. NULLs: every terminal, the last 90 days
  FUNCTION replay_rejects (p_sn IN VARCHAR2 DEFAULT NULL, p_from IN DATE DEFAULT NULL) RETURN NUMBER;
  PROCEDURE purge;   -- old traffic and rejected lines
  -- a line as the logs keep it: no password, card number, communication key, template or picture
  FUNCTION masked (p IN VARCHAR2) RETURN VARCHAR2;
END HDR_ADMS;
/

