-- ---------------------------------------------------------------- hdr_alerts.pks
CREATE OR REPLACE PACKAGE HDR_ALERTS AS
  -- The alerts of the Hader program (hader/alerts.py) inside the database, for the bell of APEX app 141:
  -- the same rules (HDR_SETTINGS alerts.<rule>.<field>, shared with the program), the same words, and each
  -- event told once (HDR_NOTIFICATIONS.AKEY, keyed as the program's alert log). What is meant for the managers
  -- reaches the bell; the program itself still tells the employees (its portal) and sends e-mail and Telegram.

  -- every minute, from HDR_JOBS.tick (after today's results are calculated)
  PROCEDURE tick;

  -- the pages of APEX app 141 a notification opens
  PAGE_DASHBOARD CONSTANT NUMBER := 1;
  PAGE_DEVICES   CONSTANT NUMBER := 6;
  PAGE_LEAVES    CONSTANT NUMBER := 11;
  PAGE_OVERTIME  CONSTANT NUMBER := 28;
  PAGE_MANUAL    CONSTANT NUMBER := 30;
  PAGE_LATE      CONSTANT NUMBER := 46;
  PAGE_ABSENT    CONSTANT NUMBER := 47;
  PAGE_EXCEPTION CONSTANT NUMBER := 55;

  -- the words of an alert, as the program writes them ({name}, {time} ... filled in)
  FUNCTION title (p_kind IN VARCHAR2) RETURN NVARCHAR2;
  FUNCTION body (p_kind IN VARCHAR2, p_name IN NVARCHAR2 DEFAULT NULL, p_time IN VARCHAR2 DEFAULT NULL,
                 p_minutes IN NUMBER DEFAULT NULL, p_device IN NVARCHAR2 DEFAULT NULL, p_what IN NVARCHAR2 DEFAULT NULL,
                 p_when IN NVARCHAR2 DEFAULT NULL, p_present IN NUMBER DEFAULT NULL, p_expected IN NUMBER DEFAULT NULL,
                 p_late IN NUMBER DEFAULT NULL, p_absent IN NUMBER DEFAULT NULL, p_offline IN NUMBER DEFAULT NULL)
    RETURN NVARCHAR2;

  -- an absence or a missing check-out is told this many minutes after the shift begins / ends at the earliest
  -- (the program's alerts.AFTER_SHIFT_MINUTES)
  AFTER_SHIFT CONSTANT NUMBER := 30;

  -- notifications older than this many days go (HDR_JOBS, once a day)
  KEEP_DAYS CONSTANT NUMBER := 90;
  PROCEDURE purge;
END HDR_ALERTS;
/

