-- ---------------------------------------------------------------- hdr_ui.pks
CREATE OR REPLACE PACKAGE HDR_UI AS
  -- What the Hader plug-ins of APEX pages read and do (terminals, an employee's biometrics, settings).
  -- Runs with the rights of the Hader schema: the APEX parsing schema needs only EXECUTE on it
  -- (HDR_UI.grant_to). Answers are JSON in plain ASCII (\u escapes), whatever the database character set.
  -- Errors are raised as ORA-206xx with an Arabic - English message for the page.

  -- terminals -------------------------------------------------------------------------------
  FUNCTION devices RETURN CLOB;
  FUNCTION commands (p_sn IN VARCHAR2, p_limit IN NUMBER DEFAULT 30) RETURN CLOB;
  -- p_action: server (a1 host, a2 port, a3 Y/N restart) / clock / info / check / reboot / reload_options /
  --           clear_log / clear_photo / clear_data / sync (every person of its area) / pull (everything it holds) /
  --           update (a1 name, a2 area id, a3 Y/N enabled) / cancel (waiting commands) / retry (failed commands) /
  --           forget (remove the terminal from the list) / punches (a1 from, a2 to: the punches of a period) /
  --           option (a1 a setting of the terminal's own, a2 its value)
  FUNCTION device_do (p_sn IN VARCHAR2, p_action IN VARCHAR2, p_a1 IN NVARCHAR2 DEFAULT NULL,
                      p_a2 IN VARCHAR2 DEFAULT NULL, p_a3 IN VARCHAR2 DEFAULT NULL) RETURN NUMBER;
  -- what is set for a terminal (its device form): English name, counted for attendance or not, time zone (hours,
  -- empty: the setting), seconds between its requests, how often and when it sends punches, at once or not.
  -- Returns 1 when the terminal is asked to read its settings again
  FUNCTION device_settings (p_sn IN VARCHAR2, p_alias_en IN VARCHAR2, p_attendance IN VARCHAR2,
                            p_time_zone IN VARCHAR2, p_heartbeat IN VARCHAR2, p_interval IN VARCHAR2,
                            p_times IN VARCHAR2, p_realtime IN VARCHAR2) RETURN NUMBER;
  PROCEDURE set_write (p_on IN VARCHAR2);   -- Y / N: changes may be sent to the terminals

  -- one employee on the terminals ------------------------------------------------------------
  FUNCTION employee (p_emp_code IN VARCHAR2) RETURN CLOB;
  -- p_action: areas (a1 = area ids 'id,id') / enroll (a1 terminal, a2 type 1 finger 2/9 face 8 palm 7 vein, a3 finger 0-9) /
  --           pull (read from the terminals of the areas) / push (send again with templates and photos) /
  --           remove (delete from the terminals of the areas)
  FUNCTION employee_do (p_emp_code IN VARCHAR2, p_action IN VARCHAR2, p_a1 IN VARCHAR2 DEFAULT NULL,
                        p_a2 IN VARCHAR2 DEFAULT NULL, p_a3 IN VARCHAR2 DEFAULT NULL) RETURN NUMBER;
  -- several employees at once, as the program's employees page: p_codes their numbers (',' or spaces); p_action
  -- set_department (p_a1 the department) / set_areas, add_areas (p_a1 the area ids 'id,id') / resign (p_a1 the
  -- date YYYY-MM-DD, today when empty) / reinstate / sync (to their area terminals again) / unsync (off them, kept
  -- here) / delete. By whoever edits employees; returns what was done.
  FUNCTION employees_batch (p_user IN VARCHAR2, p_action IN VARCHAR2, p_codes IN VARCHAR2,
                            p_a1 IN VARCHAR2 DEFAULT NULL) RETURN NVARCHAR2;
  -- one row of the employees' Excel file (the program's template): NEW or UPDATED, otherwise why not (nothing
  -- changed). The department by its code, then its name, made when not there; a new employee in the first area;
  -- one already here keeps what the row leaves empty. Never commits: the page checks a file by rolling back.
  FUNCTION employee_import (p_user IN VARCHAR2, p_code IN VARCHAR2, p_name IN NVARCHAR2 DEFAULT NULL,
                            p_name_en IN VARCHAR2 DEFAULT NULL, p_dept_code IN VARCHAR2 DEFAULT NULL,
                            p_dept IN NVARCHAR2 DEFAULT NULL, p_position IN NVARCHAR2 DEFAULT NULL,
                            p_card IN VARCHAR2 DEFAULT NULL, p_hire IN VARCHAR2 DEFAULT NULL,
                            p_mobile IN VARCHAR2 DEFAULT NULL, p_email IN VARCHAR2 DEFAULT NULL) RETURN NVARCHAR2;
  -- the schedule of several employees (p_codes: their numbers) for a day or a period (p_from .. p_to, a year at
  -- most): the timetables p_tts ('id,id'), none = a day off; what they had in those days is replaced. Returns how
  -- many employees. As the program's temporary schedule (POST /api/temp-schedules); never commits
  FUNCTION temp_set (p_codes IN VARCHAR2, p_from IN DATE, p_to IN DATE DEFAULT NULL, p_tts IN VARCHAR2 DEFAULT NULL)
    RETURN NUMBER;
  -- A page's report as a file, as the program exports its reports (hader/reports.py to_xlsx and iter_csv):
  -- sheet_start (Excel: the organisation, the title and period above the table; p_csv 'Y': a CSV file), then the
  -- cells of each row (p_kind 's' text, 'n' a number, 'h' a heading, p_width its column's width) and sheet_row,
  -- then the file. Excel takes 1,048,576 rows a sheet (p_sheet_rows): the rest go on further sheets
  PROCEDURE sheet_start (p_title IN NVARCHAR2, p_period IN NVARCHAR2 DEFAULT NULL, p_rtl IN VARCHAR2 DEFAULT 'Y',
                         p_csv IN VARCHAR2 DEFAULT 'N', p_sheet_rows IN PLS_INTEGER DEFAULT 1048576);
  PROCEDURE sheet_cell (p_value IN NVARCHAR2, p_kind IN VARCHAR2 DEFAULT 's', p_width IN NUMBER DEFAULT NULL);
  PROCEDURE sheet_row;
  FUNCTION sheet_finish RETURN BLOB;
  FUNCTION photo (p_emp_code IN VARCHAR2) RETURN BLOB;          -- the card picture, else the recognition photo

  -- card pictures (HADER_EMP_PHOTOS: what a terminal shows when the employee punches; not the recognition
  -- photo it learns the face from). One chosen here goes to the terminals of the employee's areas and a
  -- terminal does not replace it. The functions return how many terminals are told.
  FUNCTION card_photo (p_emp_code IN VARCHAR2) RETURN BLOB;     -- the card picture only
  -- a JPEG named by the employee number (1234.jpg): NULL when taken, otherwise why not
  FUNCTION card_import (p_file_name IN VARCHAR2, p_data IN BLOB) RETURN VARCHAR2;
  FUNCTION card_from_recognition (p_emp_code IN VARCHAR2, p_bio_type IN NUMBER DEFAULT 9) RETURN NUMBER;
  FUNCTION card_delete (p_emp_code IN VARCHAR2) RETURN NUMBER;  -- the terminals remove theirs too

  -- recognition photos (HDR_BIO_PHOTOS: the face photos a terminal learns a face from) -------------------
  FUNCTION bio_photo (p_emp_code IN VARCHAR2, p_bio_type IN NUMBER DEFAULT 9) RETURN BLOB;
  -- a JPEG named by the employee number (1234.jpg, 1234_face.jpg): NULL when taken, otherwise why not;
  -- p_send = 'Y' sends it on to the terminals of the employee's areas
  FUNCTION photo_import (p_file_name IN VARCHAR2, p_data IN BLOB, p_send IN VARCHAR2 DEFAULT 'N') RETURN VARCHAR2;
  FUNCTION photo_send (p_emp_code IN VARCHAR2, p_bio_type IN NUMBER DEFAULT 9) RETURN NUMBER;
  PROCEDURE photo_delete (p_emp_code IN VARCHAR2, p_bio_type IN NUMBER DEFAULT 9, p_face IN VARCHAR2 DEFAULT 'N');

  -- the bell of APEX app 141 (HDR_ALERTS) ------------------------------------------------------
  -- the latest notifications, which of them this user has read, and how many of the last 30 days are unread
  FUNCTION notes (p_user IN VARCHAR2, p_limit IN NUMBER DEFAULT 30) RETURN CLOB;
  -- one read (p_id), or every one of the last 30 days (p_id NULL)
  PROCEDURE notes_read (p_user IN VARCHAR2, p_id IN NUMBER DEFAULT NULL);

  -- the Hader assistant in APEX app 141 (HDR_AI_CHAT) ---------------------------------------------
  -- the page asks and reads; the Hader server, connected to this schema, answers (hader/ai/apex.py) and writes
  -- the reply as it grows. Every call is for one APEX user and sees that user's conversations only.
  -- p_files: the numbers of the files attached to it (ai_upload), separated by commas; without a question, the
  -- files are read
  FUNCTION ai_ask (p_user IN VARCHAR2, p_conv IN NUMBER, p_question IN VARCHAR2,
                   p_files IN VARCHAR2 DEFAULT NULL) RETURN NUMBER;   -- the request
  -- a file attached to the next question: its number, until it is sent (ai_unupload takes it back)
  -- sent in parts (a page's request holds only so much): the first without p_id gives the number, the last says
  -- p_last 'Y'; a file sent at once is one part
  FUNCTION ai_upload (p_user IN VARCHAR2, p_name IN VARCHAR2, p_data IN BLOB, p_id IN NUMBER DEFAULT NULL,
                      p_last IN VARCHAR2 DEFAULT 'Y') RETURN NUMBER;
  PROCEDURE ai_unupload (p_user IN VARCHAR2, p_id IN NUMBER);
  FUNCTION ai_upload_get (p_user IN VARCHAR2, p_id IN NUMBER, o_name OUT VARCHAR2, o_mime OUT VARCHAR2) RETURN BLOB;
  -- run (p_run = 'Y') or decline a proposal shown in the answer to request p_req
  FUNCTION ai_decide (p_user IN VARCHAR2, p_req IN NUMBER, p_action IN NUMBER, p_run IN VARCHAR2) RETURN NUMBER;
  PROCEDURE ai_stop (p_user IN VARCHAR2, p_req IN NUMBER);
  PROCEDURE ai_drop (p_user IN VARCHAR2, p_conv IN NUMBER);      -- forget a conversation (here and in Hader)
  FUNCTION ai_poll (p_user IN VARCHAR2, p_req IN NUMBER) RETURN CLOB;   -- one request: its state and reply
  FUNCTION ai_list (p_user IN VARCHAR2) RETURN CLOB;                     -- the conversations, newest first
  FUNCTION ai_open (p_user IN VARCHAR2, p_conv IN NUMBER) RETURN CLOB;   -- one conversation, every question
  -- a file the assistant made for the user (HDR_AI_FILES): its content, name and type; NULL when not theirs
  FUNCTION ai_file (p_user IN VARCHAR2, p_id IN NUMBER, o_name OUT VARCHAR2, o_mime OUT VARCHAR2) RETURN BLOB;
  -- the assistant's settings, read, saved or tested by the Hader server for a system administrator: p_request is
  -- {"method": GET / PUT / POST, "path": "/api/ai/config" or "/api/ai/test", "body": ...}; the reply is read with
  -- ai_poll. A key typed in it is kept only until the Hader server takes the request.
  FUNCTION ai_config (p_user IN VARCHAR2, p_request IN VARCHAR2) RETURN NUMBER;

  -- whose requests (leave, manual punches, overtime) a user sees and decides: the program's hader/approvals.py ------
  -- An APEX user is the account of the same name (HDR_USERS, kept by the Hader server; others added in the app).
  -- The general manager (attendance.approve_all, or system.admin) decides every department; anyone else with
  -- attendance.approve those of the departments they head or stand in for today (HDR_APPROVERS, both dates counted,
  -- none = always) and of the departments under them; with no such department, none. Without attendance.approve
  -- nobody decides anything and the request pages show every request, as before. Employees without a department are
  -- the general manager's alone. While no account is known at all (HDR_USERS empty) the schema's own jobs and scripts
  -- may everything; a user signed in to APEX never: no account, no permission.
  -- Inside APEX the signed-in user counts (p_user is taken only outside it, from the schema's owner).
  FUNCTION permissions RETURN VARCHAR2;                                                -- the program's permissions
  FUNCTION may (p_user IN VARCHAR2, p_permission IN VARCHAR2) RETURN VARCHAR2;          -- Y / N
  -- who may enter APEX app 141: A an active account of that name (its pages by its permissions), E no account but an
  -- employee the database knows (their own portal page only), N nobody (a disabled account included)
  FUNCTION member (p_user IN VARCHAR2) RETURN VARCHAR2;
  -- the first administrator of APEX app 141, from SQL Workshop, while no account is known at all
  PROCEDURE first_admin (p_user IN VARCHAR2);
  FUNCTION request_shown (p_user IN VARCHAR2, p_dept_code IN VARCHAR2) RETURN VARCHAR2;  -- Y / N: on the request pages
  FUNCTION request_decides (p_user IN VARCHAR2, p_emp_code IN VARCHAR2) RETURN VARCHAR2; -- Y / N
  -- the status a request form stores (p_kind leave / manual / overtime, p_id NULL: a new one): without attendance.approve
  -- pending; an approval or rejection of someone outside the user's departments, or of their own request, is refused
  FUNCTION request_status (p_user IN VARCHAR2, p_kind IN VARCHAR2, p_id IN NUMBER, p_emp_code IN VARCHAR2,
                           p_status IN VARCHAR2) RETURN VARCHAR2;
  PROCEDURE request_remove (p_user IN VARCHAR2, p_kind IN VARCHAR2, p_id IN NUMBER);    -- before one is removed
  -- several requests of a list decided at once (each checked as one; those not this user's left and counted);
  -- p_note: the approver's reason, told to the employee (DECISION_NOTE), the time of the decision kept (DECIDED_AT)
  FUNCTION request_decide_many (p_user IN VARCHAR2, p_kind IN VARCHAR2, p_ids IN VARCHAR2, p_status IN VARCHAR2,
                                p_note IN NVARCHAR2 DEFAULT NULL) RETURN NVARCHAR2;
  PROCEDURE request_open (p_user IN VARCHAR2, p_kind IN VARCHAR2, p_id IN NUMBER);      -- before a form shows one
  FUNCTION pending_count (p_user IN VARCHAR2, p_kind IN VARCHAR2) RETURN NUMBER;       -- waiting, of those shown
  -- the greeting of the time of day (the settings' ui.greetings, else the program's) and the user's first name
  FUNCTION greeting (p_user IN VARCHAR2) RETURN VARCHAR2;
  -- the employee's attendance source by its name (hr.sources), and the note of a day recorded otherwise than it
  -- says (hr.source_methods, hr.verify_methods, hr.source_flag; hader/att_source.py note)
  FUNCTION source_name (p_emp IN VARCHAR2) RETURN VARCHAR2;
  -- a leave beyond the HR system's balance: the warning (hr.balance_rule), else NULL
  FUNCTION balance_short (p_id IN NUMBER) RETURN NVARCHAR2;
  -- a month's lateness taken from a leave balance (hader/leave_moves.py): the month's movements made again as
  -- waiting (those posted stay), and the waiting ones posted through hr.ledger_proc (p_ids: those, else the month's)
  FUNCTION paused (p_day IN DATE) RETURN VARCHAR2;
  -- employees the HR link would not bring now (outside hr.employees_where), resigned ones with no punch on any
  -- terminal, and departments with no one: counted (p_apply N), or removed (Y: employees off the terminals too)
  FUNCTION employees_cleanup (p_user IN VARCHAR2, p_apply IN VARCHAR2 DEFAULT 'N') RETURN NVARCHAR2;     -- Y: within hr.deduct_pause
  FUNCTION moves_compute (p_user IN VARCHAR2, p_month IN VARCHAR2) RETURN VARCHAR2;
  FUNCTION moves_post (p_user IN VARCHAR2, p_month IN VARCHAR2, p_ids IN VARCHAR2 DEFAULT NULL) RETURN VARCHAR2;
  -- a leave out of its type's HR rules (hr.table_leave_rules, hr.leave_rule): the warning, else NULL
  FUNCTION leave_rules (p_id IN NUMBER) RETURN NVARCHAR2;
  -- what went beyond the limits of the employee's attendance type in the period (hader/hr_limits.py notes)
  FUNCTION limits_note (p_emp IN VARCHAR2, p_from IN DATE, p_to IN DATE) RETURN NVARCHAR2;
  FUNCTION source_note (p_emp IN VARCHAR2, p_day IN DATE) RETURN VARCHAR2;
  FUNCTION pairs_ok (p_text IN VARCHAR2, p_kind IN VARCHAR2) RETURN BOOLEAN;
  -- the attendance types of the HR schema (hr.att_owner: HR_ATTENDANCE_TYPES / _CONSTANT / _GROUPS) as shifts and
  -- each employee's schedules from p_since on (nothing before it changes), the Ramadan type in hr.ramadan's days,
  -- as the program does (hader/hr_attendance.py). p_apply 'N': only what it would do. system.admin. JSON.
  FUNCTION hr_types (p_user IN VARCHAR2, p_since IN DATE, p_apply IN VARCHAR2 DEFAULT 'N') RETURN CLOB;
  FUNCTION request_scope (p_user IN VARCHAR2) RETURN NVARCHAR2;      -- a department's approver: whose requests are shown
  -- a department's head and deputies (users.manage; no one names themselves but the system administrator; one
  -- head at a time). Returns the row's id.
  FUNCTION approver_save (p_user IN VARCHAR2, p_id IN NUMBER, p_dept_code IN VARCHAR2, p_username IN VARCHAR2,
                          p_kind IN VARCHAR2, p_start IN DATE, p_end IN DATE) RETURN NUMBER;
  PROCEDURE approver_delete (p_user IN VARCHAR2, p_id IN NUMBER);
  -- an account added in the app (users.manage); those of the program (SOURCE HADER) are the Hader server's
  PROCEDURE account_save (p_user IN VARCHAR2, p_username IN VARCHAR2, p_full_name IN NVARCHAR2, p_emp_code IN VARCHAR2,
                          p_permissions IN VARCHAR2, p_active IN VARCHAR2 DEFAULT 'Y');
  PROCEDURE account_delete (p_user IN VARCHAR2, p_username IN VARCHAR2);

  -- settings and health ----------------------------------------------------------------------
  -- the landing page of Hader in another application of the university (plug-in COM.HADER.LANDING) ------------
  FUNCTION today RETURN CLOB;          -- today at a glance: expected, present, late, absent, on leave, terminals
  -- the landing page in the university's systems (COM.HADER.LANDING): who the user is to Hader and the parts of
  -- APEX app 141 their permissions open (the same rules as its pages); nobody: nothing at all
  FUNCTION landing (p_user IN VARCHAR2) RETURN CLOB;
  FUNCTION landing_today (p_user IN VARCHAR2) RETURN CLOB;   -- today at a glance, for whoever may see attendance
  -- the dashboard (page 1) as the program's: today, the last 14 days, hours, departments, terminals, punches
  FUNCTION dashboard (p_user IN VARCHAR2) RETURN CLOB;
  -- the biometrics page (32): the terminals next to what is stored; p_fetch 'Y': all of them asked for all they hold
  FUNCTION bio_coverage (p_user IN VARCHAR2, p_fetch IN VARCHAR2 DEFAULT 'N') RETURN CLOB;
  -- the page of that application to go back to from APEX app 141 (its user menu, back to the home page): its id or alias and
  -- page, kept as apex.home; NULL to forget it
  PROCEDURE home (p_app IN VARCHAR2, p_page IN VARCHAR2);
  FUNCTION home_url (p_session IN VARCHAR2) RETURN VARCHAR2;   -- f?p=app:page:session, NULL when none is kept
  -- the employee portal of APEX app 141 (page My portal): the signed-in APEX user's own days from the database; their
  -- requests, leave balances and inbox through the Hader server (HADER_REQUESTS KIND = PORTAL, hader/apex_portal.py)
  FUNCTION me_code (p_user IN VARCHAR2) RETURN VARCHAR2;   -- the employee of an APEX user (account, e-mail or number)
  FUNCTION me (p_user IN VARCHAR2) RETURN CLOB;            -- who, today, today's punches, the last answer of Hader
  FUNCTION me_month (p_user IN VARCHAR2, p_ym IN VARCHAR2) RETURN CLOB;   -- YYYY-MM day by day and its totals
  FUNCTION me_ask (p_user IN VARCHAR2, p_action IN VARCHAR2, p_detail IN VARCHAR2 DEFAULT NULL) RETURN VARCHAR2;
  FUNCTION me_reply (p_user IN VARCHAR2, p_req IN VARCHAR2) RETURN CLOB;  -- a request's state and Hader's answer
  FUNCTION settings RETURN CLOB;
  -- the terminals' server (one terminal, or every one accepted and on): a system administrator's; how many were sent
  -- the activation key of the free edition (HDR_LICENSE.set_key): a system administrator's; empty removes it
  PROCEDURE set_license (p_key IN VARCHAR2);
  FUNCTION point_server (p_host IN VARCHAR2, p_port IN VARCHAR2, p_restart IN VARCHAR2 DEFAULT 'Y',
                         p_sn IN VARCHAR2 DEFAULT NULL) RETURN NUMBER;
  PROCEDURE set_value (p_key IN VARCHAR2, p_value IN NVARCHAR2);
  PROCEDURE demo (p_on IN VARCHAR2);   -- Y: load the sample company (HDR_DEMO), N: remove it

  -- punch lines kept aside with a database error saved again (HDR_ADMS.replay_rejects); for who controls terminals
  FUNCTION replay_rejects (p_user IN VARCHAR2, p_sn IN VARCHAR2 DEFAULT NULL, p_from IN DATE DEFAULT NULL) RETURN NUMBER;

  -- let an APEX parsing schema use the plug-ins and build pages on the Hader tables
  FUNCTION grant_to (p_schema IN VARCHAR2) RETURN VARCHAR2;
  -- the English of APEX app 141 (2.3.6): its words translated from HDR_I18N, then published as its English version
  -- (APEX_LANG: a language mapping the first time, the texts seeded, translated and published). Again after every
  -- import of the app. p_app NULL: the app of this workspace with the alias HADER (or ATTENDANCE). Returns
  -- 'texts translated / texts left in Arabic / the English version's application id'
  FUNCTION publish_english (p_app IN NUMBER DEFAULT NULL) RETURN VARCHAR2;
  FUNCTION english (p_app IN NUMBER) RETURN VARCHAR2;     -- Y: the app has its English version (publish_english)
  -- the language of the APEX session asking (en / ar; outside APEX: ar), and a text of the app in it: its English
  -- from HDR_I18N in an English session, else the Arabic as it is (the words the app writes in its own code)
  FUNCTION lang RETURN VARCHAR2;
  FUNCTION tr (p_ar IN NVARCHAR2) RETURN NVARCHAR2;
END HDR_UI;
/

